/* ============================================================
 * EnemyArtData.js —— 敌人美术数据（data URI，离线生成，同源干净）
 *
 * ① BOSS_ART：三只 BOSS 独立贴图（源 assets/bosses.png，1536x1536 纯白底，
 *    横排 左金/中蓝/右灰）。按【实际元素边界】裁切（相邻 BOSS 列间距 39~40px，
 *    取其元素包围盒，非简单三等分，绝不把相邻 BOSS 切进来）；白底用
 *    【从四边洪水填充的连通域】抠成透明（BOSS 内部白色眼睛/高光不连通外圈
 *    背景，完整保留），再做白边 un-premultiply 去晕 + 按 alpha 裁剪到内容
 *    包围盒 + Lanczos 缩放到 显示高度(90)×3 = 270px。
 * ② SLIME_STATIC_ART：史莱姆静态降级贴图（源 assets/slime_walk.mp4，取
 *    【落地姿态】那一帧，按段窗口裁切，用【到实测底色的 L1 距离】抠成透明，
 *    缩放到 显示高度(50/60)×2 像素）。手机端不支持视频播放时用它 + 蹦跳 Tween。
 *
 * data URI 在 file:// 下也能直通 WebGL 上传（本地图片文件会因跨域污染无法上传）；
 * 任一贴图解码失败由 BootScene 回退程序化占位贴图，绝不黑屏。
 * ============================================================ */
window.BOSS_ART = {
  "gold": "data:image/png;base64,",
  "blue": "data:image/png;base64,",
  "gray": "data:image/png;base64,"
};

window.SLIME_STATIC_ART = {
  "green": "data:image/png;base64,",
  "blue": "data:image/png;base64,"
};
